function c1HealStamps(){ const f=F(); if (!f.stampUgo && f.gaveFlowers) f.stampUgo=1; if (!f.stampDoc && f.pickles && !avHas('barattolo') && !avHas('vasetto') && !avHas('campione')) f.stampDoc=1; avSave(); }
/* ================= CAPITOLO 1 — PROLOGO, CASA, PIAZZA, BUROCRAZIA, EXTRA ================= */
const AV_INTRO=async()=>{
  setPose('lie');
  await avLines([
    ['voice','Ore 3:07 di notte. Il paese dorme. Tranne te, che ti sei addormentato sul divano con la bocca aperta.','3:07 a.m. The town sleeps. Except you, asleep on the sofa with your mouth open.'],
    ['me','Che dormita. Ho un sapore in bocca come se avessi leccato un posacenere. Forse l\'ho fatto.','What a nap. My mouth tastes like I licked an ashtray. Maybe I did.']]);
  setPose('idle');
  await avLines([
    ['me','Quella radio gracchia da un\'ora. O è il sindaco o è un maiale sgozzato. Stessa voce.','That radio has been crackling for an hour. Either it\'s the mayor or a pig being slaughtered. Same voice.']]);
};
/* ---------------- SOGGIORNO ---------------- */
avOn('look:radio',()=>me('Una radio a valvole del nonno. Prende solo Radio Paese: liscio, necrologi e il sindaco.','Grandpa\'s valve radio. Only gets Radio Town: ballroom music, obituaries and the mayor.'));
avOn('use:radio open:radio',async()=>{ const f=F(); setPose('play');
  await np('sindaco','📻 Cittadini! Qui parla il vostro amato sindaco Benito Pappalardo!','📻 Citizens! This is your beloved mayor Benito Pappalardo!');
  await np('sindaco','📻 Stanotte, alla vigilia della Sagra, ignoti hanno RUBATO il sacro Mestolo d\'Oro di San Pancrazio!','📻 Tonight, on the eve of the Festival, persons unknown STOLE the sacred Golden Ladle of Saint Pancras!');
  await np('sindaco','📻 Senza Mestolo niente risotto, senza risotto niente Sagra, senza Sagra niente rielezione! Cioè, niente gioia per il popolo!','📻 No Ladle, no risotto. No risotto, no Festival. No Festival, no re-election! I mean, no joy for the people!');
  await np('sindaco','📻 Chi lo ritrova avrà MILLE PIPPI e pizza gratis a vita! Gli investigatori volontari si presentino in piazza. Subito!','📻 Whoever finds it gets A THOUSAND PIPPI and free pizza for life! Volunteer investigators, report to the piazza. Now!');
  setPose('idle');
  if (!f.radio){ f.radio=1; avSave(); return me('Mille Pippi. Ci pago il bollo, l\'idraulico e lo strozzino. In quest\'ordine no, prima lo strozzino. Devo uscire. Dove cazzo sono le chiavi?','A thousand Pippi. I can pay the car tax, the plumber and the loan shark. Not in that order, shark first. I need to go out. Where the hell are my keys?'); }
  return me('Sempre la stessa solfa. Mille Pippi. Muoviti.','Same old tune. A thousand Pippi. Move it.'); });
avOn('take:radio',()=>me('Pesa più di mia suocera. E brontola uguale.','It weighs more than my mother-in-law. Grumbles the same, too.'));
avOn('look:sofa',()=>me('Il divano. Ha la forma del mio culo, scolpita in vent\'anni di onorato servizio.','The sofa. It has the shape of my arse, carved by twenty years of honourable service.'));
avOn('use:sofa',async()=>{ await meAct('sit',1800); return me('Due minuti di pace. Poi mi ricordo dei mille Pippi e mi passa.','Two minutes of peace. Then I remember the thousand Pippi and it passes.'); });
avOn('take:cushion open:cushion look:cushion',async()=>{ if (!F().cushionDone){ F().cushionDone=1; avSave(); await me('Sotto il cuscino: tre briciole, un telecomando, una caramella già succhiata e...','Under the cushion: three crumbs, a remote, an already-sucked sweet and...'); if (avCoin('cushion')) return me('Un Pippi d\'oro! Lo sapevo che il divano mi voleva bene.','A golden Pippi! I knew the sofa loved me.'); } return me('Niente chiavi qui. Solo la mia dignità, sbriciolata.','No keys here. Just my dignity, in crumbs.'); });
avOn('look:books',()=>me('"Come diventare ricchi senza fare un cazzo", volume 2. Il volume 1 non l\'ha finito nessuno. Accanto: "Il necrologio fai-da-te" e un album di francobolli del nonno.','"How to get rich doing bugger all", vol. 2. Nobody finished vol. 1. Next to it: "DIY Obituaries" and grandpa\'s stamp album.'));
avOn('take:books open:books',()=>me('Sfoglio l\'album del nonno. Francobolli svizzeri, tutti. Il nonno dice di essere andato in Svizzera "per lavoro" nel 1987. Non è mai tornato. Neanche una cartolina. Solo francobolli. Strano.','I leaf through grandpa\'s album. Swiss stamps, all of them. Grandpa went to Switzerland "for work" in 1987. Never came back. Not a postcard. Just stamps. Weird.'));
avOn('look:tv use:tv',()=>me('Televendita di materassi da tre giorni. Il presentatore sembra morto ma continua a sorridere. Come il sindaco.','Mattress infomercial for three days now. The host looks dead but keeps smiling. Like the mayor.'));
avOn('look:plant',()=>me('Una pianta finta. L\'unica che non sono riuscito ad ammazzare. Ci sto lavorando.','A fake plant. The only one I haven\'t managed to kill. Working on it.'));
avOn('look:window',()=>me('Fuori è notte ma c\'è un sole che spacca. Il comune ha tagliato i fondi al buio.','It\'s night outside but the sun is blazing. The council cut the budget for darkness.'));
/* ---------------- CUCINA ---------------- */
avOn('look:fridge',()=>me('Il frigo. Ronza come un vecchio che ha qualcosa da dire.','The fridge. Hums like an old man with something to say.'));
avOn('open:fridge',async()=>{ const f=F(); if (!f.pickles){ f.pickles=1; avAdd('barattolo'); return me('Dentro: un limone depresso, mezzo wurstel di epoca incerta e un barattolo di sottaceti. Prendo i sottaceti. Il wurstel lo lascio ai posteri.','Inside: a depressed lemon, half a frankfurter of uncertain age and a jar of pickles. I take the pickles. The frankfurter I leave for posterity.'); }
  return me('Il limone mi guarda con disprezzo. Chiudo.','The lemon looks at me with contempt. Closing.'); });
avOn('take:fridge',()=>me('Portarmi dietro il frigo? Ho già abbastanza peso sulla coscienza.','Carry the fridge? I\'ve got enough weight on my conscience.'));
avOn('look:coffee',()=>me('La moka della nonna. Mai lavata, per rispetto della tradizione e della muffa.','Grandma\'s coffee pot. Never washed, out of respect for tradition and mould.'));
avOn('take:coffee',()=>{ if (avHas('moka')||avHas('mokapiena')||avHas('caffe')||F().gaveCoffee) return me('Una moka basta. Due e mi viene la tachicardia.','One pot is enough. Two and my heart explodes.'); avAdd('moka'); return me('Prendo la moka. È vuota: il caffè è finito, come la mia carriera.','I take the coffee pot. It\'s empty: no coffee left, like my career.'); });
avOn('use:coffee',()=>me('È vuota. Succhiare la moka vuota è il punto più basso che potrei toccare. Quasi.','It\'s empty. Sucking an empty pot is the lowest I could sink. Almost.'));
avOn('look:stove',()=>me('I fornelli. L\'ultima volta che li ho accesi sono venuti i pompieri. Due volte. La seconda per una pizza.','The stove. Last time I lit it the firemen came. Twice. The second time for a pizza.'));
avOn('use:stove',()=>me('Accendere il gas senza niente sopra? Tanto vale ammazzarsi con stile.','Light the gas with nothing on it? Might as well die in style.'));
avOn('use:stove:mokapiena',async()=>{ await meAct('cook',2400); avSwap('mokapiena','caffe'); return me('Blub blub blub. Caffè bollente! E stavolta niente pompieri. Mi sento uno chef stellato. Una stella cadente.','Blub blub blub. Piping hot coffee! No firemen this time. I feel like a starred chef. A shooting star.'); });
avOn('use:stove:moka',()=>me('Scaldare una moka vuota? Così fonde e poi piango. Manca il caffè.','Heat an empty pot? It\'ll melt and I\'ll cry. Needs coffee.'));
avOn('look:sink',()=>me('Il lavandino. Piatti dell\'anno scorso che stanno sviluppando una civiltà. Appesi al rubinetto, i guanti di gomma gialli.','The sink. Last year\'s dishes developing a civilisation. Hanging from the tap, yellow rubber gloves.'));
avOn('take:sink',()=>{ if (avHas('guanti')||F().gloves) return me('I guanti li ho già. I piatti li lascio evolvere.','I\'ve got the gloves. The dishes can keep evolving.'); F().gloves=1; avAdd('guanti'); return me('Guanti di gomma gialli. Puzzano di detersivo e rassegnazione.','Yellow rubber gloves. They smell of detergent and resignation.'); });
avOn('use:sink',()=>me('Lavare i piatti? Alle tre di notte? Chi sono, un santo?','Wash the dishes? At 3 a.m.? Who am I, a saint?'));
avOn('look:ktable',()=>me('Il tavolo della cucina. C\'è un post-it: "Ricordati di non dimenticarti". Grazie, me stesso.','The kitchen table. There\'s a post-it: "Remember not to forget". Thanks, me.'));
/* ---------------- BAGNO ---------------- */
avOn('look:toilet',()=>{ if (F().keys) return me('Il cesso. Ha visto cose che nessun cesso dovrebbe vedere. Ieri sera soprattutto.','The toilet. It\'s seen things no toilet should see. Especially last night.'); F().sawKeys=1; avSave(); return me('Il cesso. In fondo luccica qualcosa... le mie chiavi! Ieri sera ero così ubriaco che ho fatto pipì con le chiavi in mano. E ho perso la presa. Su tutto.','The toilet. Something glitters at the bottom... my keys! Last night I was so drunk I peed with the keys in my hand. And lost my grip. On everything.'); });
avOn('take:toilet open:toilet',()=>{ if (F().keys) return me('Non c\'è più niente da ripescare. Grazie a Dio.','Nothing left to fish out. Thank God.'); return me(F().sawKeys?'Infilare la mano nuda lì dentro? Ho un limite. È basso, ma ce l\'ho. Servono dei guanti.':'Aprire il cesso a mani nude senza un motivo? No.', F().sawKeys?'Bare hand in there? I have limits. Low ones, but limits. I need gloves.':'Open the toilet bare-handed for no reason? No.'); });
avOn('use:toilet:guanti',async()=>{ const f=F(); if (f.keys) return me('Basta pescare nel cesso. La vita è già abbastanza dura.','Enough toilet fishing. Life is hard enough.'); if (!f.sawKeys) return me('Perché dovrei infilare le mani nel cesso? Non sono ancora così disperato. Quasi.','Why would I put my hands in the toilet? Not that desperate. Almost.');
  await meAct('squat',2200); f.keys=1; avSave(); avAdd('chiavi'); avOpen('piazza'); avTrophy('keys','Uscito di casa. Il primo passo è sempre il più schifoso.','Left the house. The first step is always the grossest.');
  return me('Ripescate! Gocciolano. Le asciugo sul pigiama. Ora posso uscire: prima tappa, la piazza.','Fished out! They drip. I wipe them on my pyjamas. Now I can go out: first stop, the piazza.'); });
avOn('use:toilet',()=>me('Non mi scappa. Per una volta.','I don\'t need to. For once.'));
avOn('use:toilet:vasetto',async()=>{ await meAct('hide',2000); avSwap('vasetto','campione'); return me('Fatto. Un campione giallo paglierino, annata 3 di notte. Lo chiudo bene. Benissimo.','Done. A straw-yellow sample, vintage 3 a.m. I close it tight. Very tight.'); });
avOn('look:bsink',()=>me('Lo specchio sopra il lavandino. Mi guardo. Sembro uno che ha perso le chiavi nel cesso. Perché lo sono.','The mirror above the sink. I look like someone who lost his keys in the toilet. Because I am.'));
avOn('use:bsink',()=>me('Mi lavo la faccia. Non migliora niente, ma almeno è bagnata.','I wash my face. Nothing improves, but at least it\'s wet.'));
avOn('look:shower',()=>me('La doccia. C\'è un ragno grosso come un gatto. Lo chiamo Gianni. Paga metà affitto.','The shower. There\'s a spider the size of a cat. I call him Gianni. He pays half the rent.'));
avOn('use:shower',()=>me('Una doccia adesso? E se Gianni si offende?','A shower now? What if Gianni gets offended?'));
avOn('look:btowel',()=>me('Un asciugamano che si regge in piedi da solo. Ha più carattere di me.','A towel that stands up on its own. It has more personality than me.'));
avOn('look:tp take:tp',()=>me('Mezzo rotolo. Da razionare come in tempo di guerra.','Half a roll. To be rationed like in wartime.'));
/* ---------------- CAMERA ---------------- */
avOn('look:bed',()=>me('Il letto. Disfatto dal 2019. È uno stile, si chiama "vissuto".','The bed. Unmade since 2019. It\'s a style, it\'s called "lived-in".'));
avOn('open:bed take:bed',async()=>{ const f=F(); if (!avHas('taccuino') && !f.notebook){ f.notebook=1; avAdd('taccuino'); await me('Sotto il cuscino c\'è il mio vecchio taccuino da investigatore. Lo usavo per spiare i vicini. Poi i vicini hanno chiamato i carabinieri.','Under the pillow, my old investigator\'s notebook. I used it to spy on the neighbours. Then the neighbours called the police.'); }
  if (avCoin('bed')) return me('E sotto il letto... un Pippi d\'oro, tra i calzini spaiati e un panino fossile.','And under the bed... a golden Pippi, among odd socks and a fossil sandwich.'); return me('Sotto il letto solo calzini e mostri. I mostri sono i calzini.','Under the bed just socks and monsters. The socks are the monsters.'); });
avOn('use:bed',async()=>{ await meAct('lie',1800); return me('Potrei dormire... e lasciare mille Pippi a qualcun altro? Mai.','I could sleep... and leave a thousand Pippi to someone else? Never.'); });
avOn('look:nightlamp',()=>me('Il comodino. Nel cassetto ci tengo le cose importanti: la lente da filatelico del nonno e le gocce per dormire che non prendo più. Le prende il gatto del vicino.','The bedside table. In the drawer I keep important stuff: grandpa\'s stamp magnifier and sleeping drops I no longer take. The neighbour\'s cat does.'));
avOn('open:nightlamp take:nightlamp',()=>{ if (avHas('lente')||F().lens) return me('Il cassetto ora contiene solo le gocce. Le lascio al gatto.','Only the drops left. I leave them for the cat.'); F().lens=1; avAdd('lente'); return me('La lente d\'ingrandimento del nonno. Ogni investigatore che si rispetti ne ha una. Io non mi rispetto, ma la prendo lo stesso.','Grandpa\'s magnifying glass. Every self-respecting investigator has one. I don\'t respect myself, but I take it anyway.'); });
avOn('look:wardrobe',()=>me('L\'armadio. Dentro c\'è l\'impermeabile beige di quando volevo fare il detective privato. Ho fatto un solo caso: il furto della mia bici. Non l\'ho risolto.','The wardrobe. Inside is the beige trench coat from when I wanted to be a private eye. One case: my stolen bike. Unsolved.'));
avOn('open:wardrobe take:wardrobe',()=>{ if (avHas('impermeabile')||F().trench) return me('Nell\'armadio restano solo grucce e scheletri. Metaforici. Spero.','Only hangers and skeletons left. Metaphorical. I hope.'); avAdd('impermeabile'); return me('Prendo l\'impermeabile. Con questo addosso sembro un investigatore. O un esibizionista. Dipende da cosa c\'è sotto.','I take the trench coat. In this I look like a detective. Or a flasher. Depends what\'s underneath.'); });
avOn('use:me:impermeabile',async()=>{ await meAct('spin',1300); F().trench=1; avDel('impermeabile'); avSave(); avApplyLook(); return me('Impermeabile addosso, bavero alzato. Ora sono un detective. Un detective in pigiama, ma il pigiama non si vede quasi.','Trench coat on, collar up. Now I\'m a detective. A detective in pyjamas, but you can barely tell.'); });
avOn('look:computer',()=>me('Il computer. Ho 214 mail non lette. 213 sono di mia suocera. L\'ultima è dell\'agenzia delle entrate. Preferisco quelle della suocera. Di poco.','The computer. 214 unread emails. 213 from my mother-in-law. The last one from the tax office. I prefer the mother-in-law\'s. Barely.'));
avOn('use:computer',()=>me('Leggo l\'ultima mail della suocera: "Ho sognato che morivi. Mi sono svegliata di buon umore." Che donna. Che donna di merda.','I read her latest email: "I dreamt you died. I woke up in a good mood." What a woman. What a shitty woman.'));
avOn('look:guitar use:guitar',async()=>{ await meAct('guitar',2200); return me('Conosco tre accordi e li suono tutti male. Il vicino batte sul muro. A tempo, almeno.','I know three chords and play them all badly. The neighbour bangs on the wall. In time, at least.'); });
avOn('look:me',()=>{ const f=F(); return me(f.trench?'Impermeabile, sguardo da duro. Sembro un detective. Di quelli che muoiono nel primo episodio.':'Sono io. In pigiama, spettinato, con l\'alito da posacenere. Un sex symbol, praticamente.', f.trench?'Trench coat, tough look. I look like a detective. The kind that dies in episode one.':'It\'s me. Pyjamas, messy hair, ashtray breath. A sex symbol, basically.'); });
/* ---------------- GIARDINO ---------------- */
avOn('look:flowers',()=>me('L\'aiuola. Gerani, una rosa malata e, in un angolo, il mio basilico. L\'unica cosa che coltivo oltre ai rancori.','The flower bed. Geraniums, a sick rose and, in a corner, my basil. The only thing I grow besides grudges.'));
avOn('take:flowers',async()=>{ const f=F(); const o=await avChoose([['Un mazzo di fiori','A bunch of flowers'],['Un po\' di basilico','Some basil'],['Niente','Nothing']]);
  if (o===0){ if (avHas('fiori')||f.gaveFlowers) return me('Ne ho già colti. Se ne colgo altri l\'aiuola mi denuncia.','I\'ve picked some already. Any more and the flower bed sues me.'); await meAct('squat',1200); avAdd('fiori'); return me('Un mazzo di gerani e la rosa malata. Romantico come un funerale. Che forse è il punto.','A bunch of geraniums and the sick rose. Romantic as a funeral. Which may be the point.'); }
  if (o===1){ if (avHas('basilico')||f.gaveBasil) return me('Il basilico l\'ho già preso. Lasciamogli qualche foglia per sopravvivere.','Already took basil. Let it keep a few leaves to survive.'); await meAct('squat',1200); avAdd('basilico'); return me('Un mazzetto di basilico. Profuma di domenica e di nonna.','A bunch of basil. Smells like Sunday and grandma.'); } });
avOn('look:grill',()=>me('Il barbecue. Le salsicce di Ferragosto sono ancora lì, carbonizzate, come reperti di Pompei.','The grill. The August sausages are still there, charred like relics from Pompeii.'));
avOn('use:grill open:grill',async()=>{ await meAct('squat',1200); if (avCoin('grill')) return me('Rovisto nella cenere... un Pippi d\'oro! Chi l\'ha messo qui? Io, ubriaco, probabilmente.','I dig in the ashes... a golden Pippi! Who put it here? Drunk me, probably.'); return me('Cenere e salsicce fossili. Basta archeologia.','Ash and fossil sausages. Enough archaeology.'); });
avOn('look:hammock',()=>me('L\'amaca. Il mio ufficio.','The hammock. My office.'));
avOn('use:hammock',async()=>{ await meAct('lie',1800); return me('Dondolo e penso. Penso a mille Pippi. Mi alzo.','I swing and think. I think of a thousand Pippi. I get up.'); });
avOn('look:tree',()=>me('Un albero. Ogni tanto mi tira le pigne in testa. Credo sia personale.','A tree. Now and then it throws pine cones at my head. I think it\'s personal.'));
/* ---------------- GARAGE ---------------- */
avOn('look:bench',()=>me('Il banco attrezzi. Tra viti spaiate e una foto di Padre Pio c\'è una torcia.','The workbench. Between odd screws and a picture of a saint there\'s a torch.'));
avOn('take:bench open:bench',()=>{ if (avHas('torcia')||F().torch) return me('Ho già la torcia. Padre Pio lo lascio lì, mi guarda male.','Already have the torch. The saint stays, he\'s judging me.'); F().torch=1; avAdd('torcia'); return me('Presa la torcia. Funziona pure. È un miracolo. Ecco a cosa serviva il santo.','Got the torch. It even works. A miracle. So that\'s what the saint is for.'); });
avOn('look:tools',()=>me('Attrezzi appesi in ordine perfetto. Li ha appesi mia moglie. Se ne sposto uno, lo sa. Lo sa sempre. Tra gli altri, un\'ascia.','Tools hung in perfect order. My wife did it. If I move one, she knows. She always knows. Among them, an axe.'));
avOn('take:tools',()=>{ const f=F(); if (avHas('ascia')||f.axe) return me('Ho già l\'ascia. Se prendo altro mia moglie chiede il divorzio. Ma potrebbe essere un\'idea.','Already have the axe. Take more and my wife files for divorce. Might be an idea though.'); if (!f.totoWood) return me('Prendere l\'ascia alle tre di notte senza un motivo? Così poi i vicini parlano. Più di quanto già fanno.','Take the axe at 3 a.m. for no reason? Then the neighbours talk. More than they already do.'); f.axe=1; avAdd('ascia'); return me('Prendo l\'ascia. Lascio un biglietto per mia moglie: "Non è come sembra". Così si preoccupa di più.','I take the axe. I leave my wife a note: "It\'s not what it looks like". So she worries more.'); });
avOn('look:jerry',()=>me('Una tanica di benzina. Meglio non pensarci vicino al barbecue. O vicino alla suocera.','A jerry can of petrol. Better not think about it near the grill. Or near the mother-in-law.'));
avOn('look:tyres',()=>me('Gomme vecchie. Una ha un buco. Anche l\'altra. Tutte hanno un buco, sono gomme.','Old tyres. One has a hole. So does the other. They all have holes, they\'re tyres.'));
avOn('open:tyres take:tyres use:tyres',async()=>{ await meAct('squat',1000); if (avCoin('tyres')) return me('Dentro una gomma, un Pippi d\'oro. Il nascondiglio del nonno, scommetto.','Inside a tyre, a golden Pippi. Grandpa\'s stash, I bet.'); return me('Gomme vuote. Come le mie promesse.','Empty tyres. Like my promises.'); });
/* ---------------- MANSARDA ---------------- */
avOn('look:trunk',()=>me('Il baule del nonno. Lucchetto a combinazione, quattro cifre. Sopra c\'è scritto col pennarello: "L\'anno in cui sono partito. Chi non lo sa, non lo apra."','Grandpa\'s trunk. Four-digit combination lock. Written on top in marker: "The year I left. Whoever doesn\'t know it, keep out."'));
avOn('open:trunk take:trunk use:trunk',async()=>{ const f=F(); if (f.trunk) return me('Vuoto. A parte l\'odore di naftalina e di segreti.','Empty. Apart from the smell of mothballs and secrets.');
  const c=await avCode(4, T('🔒 Lucchetto del baule','🔒 Trunk lock')); if (c===null) return;
  if (c!=='1987') return me(['Clic. Niente. Il nonno mi prende per il culo anche da lontano.','Niente. Prima di tirare a caso dovrei cercare un indizio. Tipo da qualche parte dove il nonno teneva le date.'][Math.random()<.5?0:1], ['Click. Nothing. Grandpa mocks me even from far away.','Nothing. Before guessing I should look for a clue. Somewhere grandpa kept dates.'][0]);
  await meAct('squat',1200); f.trunk=1; avSave(); avAdd('retino'); avAdd('baffi');
  return me('Clac! Dentro: un retino da pesca, dei baffi finti e un passaporto con la sua foto e il nome "Ernesto Che Guevara". Il nonno aveva una vita segreta. Il passaporto lo lascio lì: ha l\'aria di essere un reato.','Clack! Inside: a fishing net, a fake moustache and a passport with his photo and the name "Ernesto Che Guevara". Grandpa had a secret life. I leave the passport: it looks like a crime.'); });
avOn('look:boxes',()=>me('Scatoloni di addobbi di Natale e una foto del nonno con valigia, sbiadita. C\'è una data scritta piccolissima, non si legge.','Boxes of Christmas decorations and a faded photo of grandpa with a suitcase. There\'s a tiny date written on it, unreadable.'));
avOn('use:boxes:lente',async()=>{ await meAct('look',1500); F().sawDate=1; avSave(); return me('Con la lente leggo: "Parto per la Svizzera. 3 marzo 1987. Non cercatemi. Soprattutto tu, Gisella." Gisella era la nonna. Bel rapporto.','With the glass I read: "Leaving for Switzerland. 3 March 1987. Don\'t look for me. Especially you, Gisella." Gisella was grandma. Lovely marriage.'); });
avOn('open:boxes',()=>me('Palline di Natale, un presepe senza Gesù e una renna con un occhio solo. Il Natale in questa casa è sempre stato un horror.','Baubles, a nativity with no baby Jesus and a one-eyed reindeer. Christmas here was always a horror.'));
avOn('look:telescope use:telescope',async()=>{ await meAct('look',1500); return me('Punto il telescopio sul paese. Vedo la spiaggia, il porto, il faro... e il sindaco in piazza che si mette le dita nel naso in diretta radio.','I point the telescope at the town. I see the beach, the harbour, the lighthouse... and the mayor in the piazza picking his nose live on the radio.'); });
avOn('look:ghost',()=>me('Un lenzuolo sopra una sedia. Spero.','A sheet over a chair. I hope.'));
avOn('take:ghost open:ghost',()=>me('No. Se sotto c\'è un fantasma, preferisco non saperlo. Se c\'è la nonna, ancora meno.','No. If there\'s a ghost under there, I\'d rather not know. If it\'s grandma, even less.'));
avOn('look:pingpong use:pingpong',()=>me('Il tavolo da ping pong. Ci gioco da solo. E perdo.','The ping-pong table. I play alone. And lose.'));
/* ---------------- CANTINA & BUNKER ---------------- */
AV_ENTER.cellar={ before:async()=>{ if (!avHas('torcia')){ await me('In cantina al buio? Ho visto troppi film horror. E lì sotto c\'è il nonno. Cioè, la sua grappa. Serve una luce.','The cellar in the dark? I\'ve seen too many horror films. And grandpa\'s down there. His grappa, I mean. I need a light.'); return false; } },
  after:async()=>{ if (!F().cellarLit){ F().cellarLit=1; avSave(); await me('Accendo la torcia. Ragnatele, botti e un odore di nonno conservato sotto spirito.','I switch on the torch. Cobwebs, barrels and a smell of grandpa preserved in spirits.'); } } };
avOn('look:barrels',()=>{ const f=F(); if (!f.trapdoor){ f.trapdoor=1; avSave(); return me('Le botti del nonno. Una dice "GRAPPA 70°. NON BERE. NONNO". Dietro le botti, sul pavimento... una botola che non avevo mai visto!','Grandpa\'s barrels. One says "GRAPPA 70°. DON\'T DRINK. GRANDPA". Behind them, on the floor... a trapdoor I\'d never seen!'); } return me('Le botti del nonno. "GRAPPA 70°. NON BERE." Il nonno era un uomo di poche parole e molti gradi.','Grandpa\'s barrels. "GRAPPA 70°. DON\'T DRINK." Grandpa was a man of few words and many degrees.'); });
avOn('take:barrels open:barrels use:barrels',async()=>{ if (avHas('grappa')) return me('Una bottiglia basta. Due e finisco al pronto soccorso. Tre e al cimitero.','One bottle\'s enough. Two and I end up in A&E. Three, in the cemetery.'); await meAct('squat',1500); F().grappaHalf=0; avAdd('grappa'); return me('Riempio una bottiglia di grappa. Solo i vapori mi hanno sturato il naso e un orecchio.','I fill a bottle with grappa. The fumes alone unblocked my nose and one ear.'); });
avOn('look:salami',()=>me('Salami appesi. Il nonno li chiamava "il fondo pensione".','Hanging salami. Grandpa called them "the pension fund".'));
avOn('take:salami',()=>me('Se ne manca uno il nonno lo sa. Anche dalla Svizzera. Anche da morto, se è morto.','If one\'s missing grandpa knows. Even from Switzerland. Even dead, if he\'s dead.'));
avOn('look:wine take:wine',()=>me('Vino della casa. Annata: "boh". Etichetta: "per gli ospiti che odio".','House wine. Vintage: "dunno". Label: "for guests I hate".'));
avOn('look:trapdoor',()=>me('Una botola di ferro con la scritta "PRIVATO — S.d.P.". Cosa cazzo è S.d.P.?','An iron trapdoor marked "PRIVATE — P.S.". What the hell is P.S.?'));
avOn('open:trapdoor use:trapdoor',()=>{ avOpen('bunker'); avGoLater('bunker'); });
AV_ENTER.bunker={ after:async()=>{ if (!F().bunkerSeen){ F().bunkerSeen=1; avSave(); avTrophy('bunker','Hai trovato il bunker del nonno.','Found grandpa\'s bunker.'); await me('Un bunker. Sotto casa mia. Con scatolette, una radio e un cartello radioattivo. Il nonno non era in Svizzera "per lavoro". O forse sì, ma che lavoro?','A bunker. Under my house. With tins, a radio and a radioactive sign. Grandpa wasn\'t in Switzerland "for work". Or maybe he was, but what work?'); } } };
avOn('look:shelves',()=>me('Scatolette di fagioli del 1985. Bastano per sopravvivere a una guerra nucleare. Non alla flatulenza conseguente.','Tins of beans from 1985. Enough to survive a nuclear war. Not the ensuing flatulence.'));
avOn('take:shelves open:shelves',async()=>{ await meAct('squat',1000); if (avCoin('bunker')) return me('Dietro i fagioli, un Pippi d\'oro. E un biglietto: "Per le emergenze. Tipo il bollo."','Behind the beans, a golden Pippi. And a note: "For emergencies. Like car tax."'); return me('Solo fagioli. Tantissimi fagioli. Troppi.','Just beans. So many beans. Too many.'); });
avOn('look:bradio use:bradio',async()=>{ await meAct('type',1600); return me('Accendo la radio da campo. Bip-bip-biiip. È Morse. Dice: "IL CORVO VOLA BASSO". Poi solo pubblicità di materassi. Anche qui.','I switch on the field radio. Beep-beep-beeep. It\'s Morse. It says: "THE CROW FLIES LOW". Then mattress adverts. Even here.'); });
avOn('look:poster',()=>me('Un foglio appeso: "Società del Pippi — Verbale n.1: il tesoro resta dov\'è finché il Mestolo non indica la via." Il Mestolo? Quel Mestolo?','A sheet on the wall: "Pippi Society — Minutes no.1: the treasure stays where it is until the Ladle shows the way." The Ladle? THAT Ladle?'));
avOn('take:poster',()=>{ if (avHas('tessera')) return me('Ho già preso tutto quello che c\'era sotto.','Already took what was under it.'); avAdd('tessera'); return me('Stacco il foglio: sotto c\'è una tessera con un corvo barrato e la scritta "Società del Pippi — Socio n.7: Ernesto". Ernesto. Il nonno.','I pull the sheet off: under it is a card with a crossed-out crow and "Pippi Society — Member no.7: Ernesto". Ernesto. Grandpa.'); });
avOn('look:cot use:cot',()=>me('Una branda. Sul cuscino c\'è un capello bianco. Recente. Molto recente. Brrr.','A camp bed. On the pillow there\'s a white hair. Recent. Very recent. Brrr.'));
avOn('look:bdoor open:bdoor',()=>me('Una porta blindata. Chiusa. C\'è un buco della serratura a forma di mestolo. Ma che cazzo...','A blast door. Locked. The keyhole is shaped like a ladle. What the hell...'));
avOn('look:radar',()=>me('Un radar. Lampeggia un puntino sopra il faro. Poi sparisce.','A radar. A dot blinks over the lighthouse. Then vanishes.'));
avOn('look:tessera',()=>me('Tessera della Società del Pippi, socio n.7: il nonno. Sul retro: "Fidati solo di chi non ha piume."','Pippi Society card, member no.7: grandpa. On the back: "Trust only those without feathers."'));
/* ---------------- PIAZZA & SINDACO ---------------- */
AV_ENTER.piazza={ after:async()=>{ const f=F(); if (!f.piazzaSeen){ f.piazzaSeen=1; avSave(); await np('sindaco','Investigatori! Dove sono gli investigatori?! Ah, ecco uno. Uno solo. In pigiama. Il paese è finito.','Investigators! Where are the investigators?! Ah, here\'s one. One. In pyjamas. This town is finished.'); } } };
avOn('look:sindaco',()=>me('Il sindaco Benito Pappalardo. Ha più medaglie che voti, più mento che idee.','Mayor Benito Pappalardo. More medals than votes, more chins than ideas.'));
avOn('talk:sindaco',async()=>{ const f=F();
  if (f.endDone) return np('sindaco','Eroe! Ti farei una statua, ma il bilancio è quello che è. Ti faccio un busto. Piccolo. Di cartone.','Hero! I\'d build you a statue, but the budget is what it is. I\'ll do you a bust. Small. Cardboard.');
  await avTalk('sindaco',[
    {id:'job', q:['Voglio indagare sul Mestolo.','I want to investigate the Ladle.'], when:()=>!f.modulo, run:async()=>{
      if (!f.trench) return np('sindaco','In pigiama? Sembri uno scappato dalla neuro. Torna vestito da persona seria. O almeno da detective.','In pyjamas? You look like a mental-ward escapee. Come back dressed like a serious person. Or at least a detective.');
      await np('sindaco','Impermeabile! Ah, finalmente uno professionale. Però, burocrazia: per diventare Investigatore Comunale serve il Modulo B-52 con tre timbri.','A trench coat! Finally a professional. But, red tape: to become Town Investigator you need Form B-52 with three stamps.');
      await np('sindaco','Uno: certificato di sana e robusta costituzione, dal Dottor Bisturi in ospedale. Due: certificato di esistenza in vita, dal becchino al cimitero.','One: certificate of sound health, from Dr. Scalpel at the hospital. Two: certificate of being alive, from the gravedigger at the cemetery.');
      await np('sindaco','Tre: parere favorevole della Pro Loco, cioè Nonna Pina, al karaoke. Senza timbri niente distintivo. Senza distintivo i sospettati ti sputano in faccia.','Three: approval from the Tourist Board, meaning Granny Pina, at the karaoke. No stamps, no badge. No badge, the suspects spit in your face.');
      f.modulo=1; avSave(); avAdd('modulo'); avOpen('hospital'); avOpen('cimitero'); avOpen('karaoke');
      return me('Un certificato per dimostrare che sono vivo. Questo paese è un capolavoro.','A certificate to prove I\'m alive. This town is a masterpiece.'); }},
    {id:'stamps', q:['Ho il Modulo B-52 con i tre timbri.','I have Form B-52 with all three stamps.'], when:()=>f.modulo && !f.distintivo, run:async()=>{
      c1HealStamps(); const n=(f.stampDoc?1:0)+(f.stampUgo?1:0)+(f.stampPina?1:0);
      if (n<3) return np('sindaco',`Ne vedo ${n} su tre. Io i numeri li so contare. Più o meno. Torna quando li hai tutti.`,`I see ${n} out of three. I can count. Roughly. Come back with all of them.`);
      if (!avHas('marca')){ f.needBollo=1; avSave(); await np('sindaco','Tre timbri, bene. Ma... e la marca da bollo? Il Modulo B-52 senza marca da bollo da 16 Pippi è carta igienica. Costosa, ma carta igienica.','Three stamps, good. But... where\'s the revenue stamp? Form B-52 without a 16-Pippi revenue stamp is toilet paper. Expensive, but toilet paper.');
        return np('sindaco','Le marche da bollo le vende Nico al bar, fa anche da tabaccheria. E da banco dei pegni. E da agenzia matrimoniale.','Nico sells revenue stamps at the bar, it\'s also the tobacconist. And pawnshop. And dating agency.'); }
      await np('sindaco','Tre timbri! Ti nomino ufficialmente Investigatore Comunale Volontario Non Retribuito Fino a Risultato!','Three stamps! I officially appoint you Volunteer Town Investigator, Unpaid Until Results!');
      f.distintivo=1; avSave(); avDel('marca'); avSwap('modulo','distintivo'); avTrophy('distintivo','Investigatore comunale: tre timbri e un\'umiliazione.','Town investigator: three stamps and one humiliation.');
      await np('sindaco','Stanotte tre persone non hanno un alibi. Tonino il Liscio, un poco di buono che puzza di pesce. La Contessa Vanda, che gioca a poker col diavolo.','Tonight three people have no alibi. Slick Tonino, a lowlife who smells of fish. Countess Vanda, who plays poker with the devil.');
      await np('sindaco','E il mio assessore Gaspare, che dice di essere stato al porto "a controllare le reti". Ma lui è onesto, ci metto la mano sul fuoco. Quella di un altro.','And my councillor Gaspare, who says he was at the harbour "checking the nets". But he\'s honest, I\'d put my hand in the fire for him. Someone else\'s hand.');
      avOpen('porto'); avOpen('beach');
      return me('Tre sospettati. Un mestolo. Una notte. E io senza caffè. Cominciamo.','Three suspects. One ladle. One night. And me without coffee. Let\'s go.'); }},
    {id:'who', q:['Chi può averlo rubato?','Who could have stolen it?'], run:()=>np('sindaco','Chiunque! Questo paese è pieno di ladri. Io lo so, li ho fatti assumere quasi tutti in comune.','Anyone! This town is full of thieves. I know, I hired most of them at the town hall.')},
    {id:'ladle', q:['Cos\'ha di speciale questo Mestolo?','What\'s so special about this Ladle?'], run:async()=>{ await np('sindaco','Oro massiccio, 1683. San Pancrazio ci girò il risotto che sfamò il paese durante la peste. Poi morirono tutti lo stesso, ma sazi.','Solid gold, 1683. Saint Pancras stirred the risotto that fed the town during the plague. Then everyone died anyway, but full.'); return np('sindaco','Si dice che sotto il manico ci sia un\'incisione che nessuno sa leggere. Leggende. Come la mia onestà.','They say there\'s an engraving under the handle no one can read. Legends. Like my honesty.'); }},
    {id:'money', q:['Mille Pippi, davvero?','A thousand Pippi, really?'], run:()=>np('sindaco','Mille. Lordi. Poi ci sono le tasse comunali, che decido io. Ma è un dettaglio.','A thousand. Gross. Then there\'s council tax, which I set. But that\'s a detail.')},
    {id:'insult', q:['Lo sa che in paese la chiamano "il Prosciutto"?','You know people call you "the Ham"?'], once:true, run:()=>np('sindaco','Chi? Fuori i nomi! Li faccio multare tutti. Per divieto di sosta. Anche quelli senza macchina.','Who? Names! I\'ll fine them all. For illegal parking. Even the ones without cars.')}
  ]); });
avOn('give:sindaco:modulo',()=>AV_S['talk:sindaco']());
avOn('give:sindaco:distintivo',()=>np('sindaco','Te l\'ho appena dato, cretino. Tienilo, che costa. Cioè, non costa niente, ma fa figura.','I just gave you that, you idiot. Keep it. It\'s worth something. Well, nothing, but it looks good.'));
avOn('look:peppe',()=>me('Nonno Peppe. Novantun anni, tre bypass, zero filtri. Ha visto tutto, dice. Anche lo sbarco sulla luna, dal vivo, dalla Luna.','Grandpa Peppe. Ninety-one, three bypasses, zero filter. Says he\'s seen everything. Even the moon landing, live, from the Moon.'));
avOn('talk:peppe',async()=>{ const f=F(); await avTalk('peppe',[
  {id:'night', q:['Hai visto qualcosa stanotte?','Did you see anything tonight?'], run:async()=>{ await np('peppe','Alle due ero sveglio. Alla mia età la prostata comanda e io obbedisco. Ho visto uno col ciuffo lucido come una padella che correva col mestolo sotto il braccio.','At two I was awake. At my age the prostate gives orders and I obey. I saw a guy with a quiff shiny as a frying pan running with the ladle under his arm.');
    await np('peppe','Puzzava di pesce e di brillantina. È corso verso la spiaggia, dove sta quel contrabbandiere coi baffi.','He stank of fish and hair gel. Ran towards the beach, where that moustached smuggler hangs out.'); avOpen('beach'); f.peppeTip=1; avSave(); }},
  {id:'contessa', q:['Conosci la Contessa Vanda?','Do you know Countess Vanda?'], run:()=>np('peppe','La Contessa? Ha seppellito tre mariti. Tutti morti di infarto al tavolo da poker. Io con lei non gioco nemmeno a tombola.','The Countess? She buried three husbands. All dropped dead of heart attacks at the poker table. I won\'t even play bingo with her.')},
  {id:'gaspare', q:['E l\'assessore Gaspare?','And Councillor Gaspare?'], run:()=>np('peppe','Gaspare? Ha la faccia di uno che vende l\'acqua al mare e il mare ci crede. Sorride sempre. I denti glieli ha pagati il comune.','Gaspare? Face of a man who\'d sell water to the sea and the sea would buy it. Always smiling. The council paid for his teeth.')},
  {id:'grandpa', q:['Conoscevi mio nonno Ernesto?','Did you know my grandpa Ernesto?'], run:()=>np('peppe','Ernesto... giocavamo a carte. Poi un giorno parlava di un corvo, di un tesoro, di una società segreta. Il giorno dopo era in Svizzera. Io pensavo avesse un\'amante. Magari due.','Ernesto... we played cards. Then one day he talked about a crow, a treasure, a secret society. The next day he was in Switzerland. I thought he had a mistress. Maybe two.')},
  {id:'death', q:['Come stai, Peppe?','How are you, Peppe?'], run:()=>np('peppe','Ogni mattina leggo i necrologi. Se non ci sono, mi faccio la barba. Oggi me la sono fatta.','Every morning I read the obituaries. If I\'m not in them, I shave. Today I shaved.')}
  ]); });
avOn('give:peppe:grappa',()=>np('peppe','Grappa? Il dottore me l\'ha vietata. Il dottore è morto l\'anno scorso. Dammi qua. ...No, scherzo, tienila, ti serve più che a me.','Grappa? The doctor forbade it. The doctor died last year. Gimme. ...No, kidding, keep it, you need it more.'));
avOn('look:nico',()=>me('Nico il barista. Fa il caffè migliore del paese e i pettegolezzi peggiori. Paga in natura: notizie per caffè.','Nico the barista. Best coffee in town, worst gossip. Trades in kind: news for coffee.'));
avOn('talk:nico',async()=>{ const f=F(); await avTalk('nico',[
  {id:'coffee', q:['Mi dai un pacco di caffè?','Can I have a bag of coffee?'], run:async()=>{ if (f.gotPowder) return np('nico','Te l\'ho già dato. Non sono la Caritas.','Already gave you one. I\'m not a charity.');
    if (!f.toninoConf) return np('nico','Il caffè costa. Qui si paga in pettegolezzi. Portami una notizia vera sul Mestolo, una che non sa nessuno, e il caffè è tuo.','Coffee costs. Here you pay in gossip. Bring me real news about the Ladle, something nobody knows, and the coffee\'s yours.');
    await me('Tonino il Liscio ha rubato il Mestolo su commissione di uno con la maschera da corvo, e poi l\'ha perso a poker con la Contessa.','Slick Tonino stole the Ladle for a guy in a crow mask, then lost it at poker to the Countess.');
    await np('nico','CAZZO. Questa la vendo a tutto il paese entro le sei. Ecco il caffè, pagato e strapagato.','HOLY SHIT. I\'ll sell this to the whole town by six. Here\'s the coffee, paid in full.'); f.gotPowder=1; avSave(); avAdd('polvere'); }},
  {id:'contessa', q:['Dove trovo la Contessa?','Where do I find the Countess?'], run:async()=>{ await np('nico','Al privé, ogni notte. Ma lì entri solo con l\'invito e i capelli impeccabili. Gli inviti li stampa DJ Max in discoteca. I capelli... auguri.','At the privé, every night. But you only get in with an invitation and impeccable hair. DJ Max prints the invitations at the disco. The hair... good luck.'); avOpen('disco'); avOpen('prive'); }},
  {id:'gossip', q:['Novità in paese?','Any news in town?'], run:()=>np('nico','Il marito della farmacista è morto ridendo. Lei dice di una barzelletta. Io dico del topicida nel tiramisù. Ma non ho prove.','The pharmacist\'s husband died laughing. She says it was a joke. I say rat poison in the tiramisu. No proof though.')},
  {id:'gym', q:['C\'è una palestra in paese?','Is there a gym in town?'], once:true, run:async()=>{ await np('nico','Quella di Rocky. Se fai 25 flessioni in 10 secondi ti dà un premio. L\'ultimo che ci ha provato ora parla con le piante.','Rocky\'s. Do 25 push-ups in 10 seconds and he gives you a prize. The last guy who tried now talks to plants.'); avOpen('gym'); }},
  {id:'woods', q:['E il bosco?','And the woods?'], once:true, run:async()=>{ await np('nico','Ci vive Rino l\'eremita. Mangia funghi, parla con i corvi e prevede il futuro. Male, ma lo prevede.','Rino the hermit lives there. Eats mushrooms, talks to crows and predicts the future. Badly, but he does.'); avOpen('woods'); }}
  ]); });
avOn('look:board',()=>me('"CERCASI MESTOLO D\'ORO. Ricompensa 1000 Pippi. Chi sa parli. Chi non sa stia zitto. — Il Sindaco". Sotto, qualcuno ha scritto: "Il Corvo vede tutto". Bella grafia, inquietante.','"WANTED: GOLDEN LADLE. Reward 1000 Pippi. If you know, talk. If you don\'t, shut up. — The Mayor". Below, someone wrote: "The Crow sees all". Nice handwriting, creepy.'));
avOn('use:board:lente',()=>me('Con la lente: la scritta "Il Corvo vede tutto" è fatta con inchiostro nero e... una piuma, non una penna. Teatrale, il bastardo.','Through the glass: "The Crow sees all" is written in black ink and... with a feather, not a pen. Theatrical bastard.'));
avOn('look:cafe use:cafe',()=>me('Il tavolino del bar. Prenotato dai vecchietti dal 1974. Se ti siedi, ti spiegano la politica. Per tre ore.','The café table. Booked by the old boys since 1974. Sit down and they\'ll explain politics. For three hours.'));
avOn('look:gelato use:gelato',()=>me('Il gelataio è chiuso. Cartello: "Torno subito". Da martedì. Da quale martedì non si sa.','The ice-cream man is shut. Sign: "Back soon". Since Tuesday. Which Tuesday, nobody knows.'));
/* ---------------- OSPEDALE ---------------- */
avOn('look:bisturi',()=>me('Il Dottor Bisturi. Medico, chirurgo, veterinario part-time. Gli animali sopravvivono di più.','Dr. Scalpel. Doctor, surgeon, part-time vet. The animals survive more often.'));
avOn('talk:bisturi',async()=>{ const f=F(); await avTalk('bisturi',[
  {id:'cert', q:['Mi serve il certificato di sana costituzione.','I need a certificate of sound health.'], when:()=>f.modulo && !f.stampDoc, run:async()=>{ await np('bisturi','Sano tu? Con quella faccia? Ti visito, ma prima mi serve un campione di urina. Fresco. Il barattolo portalo tu, qui li usiamo per i sottaceti.','You, healthy? With that face? I\'ll examine you, but first I need a urine sample. Fresh. Bring your own jar, here we use them for pickles.'); f.docAsked=1; avSave(); }},
  {id:'hosp', q:['Com\'è la situazione qui?','How are things here?'], run:()=>np('bisturi','Due pazienti stanotte: uno caduto dalle scale, uno caduto dalla moglie. Cioè, dalla moglie col mattarello. Il primo sta meglio.','Two patients tonight: one fell down the stairs, one fell to his wife. With a rolling pin. The first is doing better.')},
  {id:'death', q:['Qual è la cosa più strana che hai visto?','Weirdest thing you\'ve seen?'], once:true, run:()=>np('bisturi','Un uomo morto due volte. La prima l\'abbiamo dichiarato noi, la seconda sua moglie quando ha visto il conto del funerale.','A man who died twice. First we declared it, second his wife did when she saw the funeral bill.')},
  {id:'crow', q:['Hai mai sentito parlare del Corvo?','Ever heard of the Crow?'], when:()=>f.toninoConf, run:()=>np('bisturi','Il Corvo... trent\'anni fa curai un uomo con una ferita da becco. Disse "Il Corvo non perdona", poi morì. Di ridere, perché l\'infermiera era inciampata.','The Crow... thirty years ago I treated a man with a beak wound. He said "The Crow never forgives", then died. Laughing, because the nurse tripped.')}
  ]); });
avOn('give:bisturi:campione',async()=>{ const f=F(); f.stampDoc=1; avDel('campione'); await npcAct('bisturi','look',1800);
  await np('bisturi','Mmm. Colore paglierino, profumo di grappa e disperazione. Colesterolo da record, fegato da alpino, pressione da pentola.','Hmm. Straw-coloured, notes of grappa and despair. Record cholesterol, alpine liver, pressure-cooker blood pressure.');
  await np('bisturi','Insomma: un rottame. Ma vivo. Timbro! Sana e robusta costituzione. Sana no, robusta sì.','In short: a wreck. But alive. Stamp! Sound and robust health. Not sound, but robust.');
  avSave(); return me('Un timbro. Uno su tre. Il primo pagato in pipì.','One stamp. One of three. The first paid in pee.'); });
avOn('give:bisturi:barattolo give:bisturi:vasetto',()=>np('bisturi','Il barattolo va riempito, genio. Con qualcosa di tuo. Liquido. Giallo. Ci arrivi?','The jar needs filling, genius. With something of yours. Liquid. Yellow. Getting there?'));
avOn('use:me:barattolo',async()=>{ await meAct('eat',2200); avSwap('barattolo','vasetto'); return me('Mi mangio tutti i sottaceti. Cetrioli, cipolline, carote. Ora ho un barattolo vuoto e un\'acidità di stomaco che potrebbe sciogliere il municipio.','I eat all the pickles. Gherkins, onions, carrots. Now I have an empty jar and heartburn that could melt the town hall.'); });
avOn('use:me:vasetto',()=>{ if (H.room!=='bathroom') return me('Qui? Davanti a tutti? Neanche io sono così. Lo faccio in bagno, a casa, da persona civile. Più o meno.','Here? In front of everyone? Even I\'m not like that. At home, in the bathroom, like a civilised person. Sort of.'); return AV_S['use:toilet:vasetto'](); });
avOn('look:rosy',()=>me('Rosy l\'infermiera. Ha fatto più punture lei che una colonia di zanzare.','Rosy the nurse. She\'s given more injections than a mosquito colony.'));
avOn('talk:rosy',async()=>{ await avTalk('rosy',[
  {id:'hi', q:['Come va il turno?','How\'s the shift?'], run:()=>np('rosy','Dodici ore in piedi, un caffè e un paziente che mi ha chiesto di sposarlo prima di morire. È sopravvissuto. Ora devo sposarlo.','Twelve hours standing, one coffee and a patient who asked me to marry him before dying. He survived. Now I have to marry him.')},
  {id:'doc', q:['Che tipo è il Dottor Bisturi?','What\'s Dr. Scalpel like?'], run:()=>np('rosy','Bravissimo. Ha solo un piccolo difetto: si dimentica le cose. Dentro i pazienti. Forbici, garze, una volta l\'orologio.','Brilliant. Just one tiny flaw: he forgets things. Inside patients. Scissors, gauze, once his watch.')},
  {id:'cabinet', q:['Cosa c\'è in quell\'armadietto?','What\'s in that cabinet?'], once:true, run:()=>np('rosy','Farmaci scaduti, la mia merenda e la pensione del primario. Non toccare niente. Soprattutto la merenda.','Expired drugs, my snack and the head doctor\'s pension. Touch nothing. Especially the snack.')}
  ]); });
avOn('look:cabinet',()=>me('Un armadietto bianco. Sulla porta: "Farmaci. E merenda di Rosy. NON TOCCARE."','A white cabinet. On the door: "Drugs. And Rosy\'s snack. DO NOT TOUCH."'));
avOn('open:cabinet',async()=>{ await meAct('squat',1000); if (avCoin('cabinet')) return me('Tra le aspirine scadute, un Pippi d\'oro. La merenda la lascio. Ho paura di Rosy.','Among expired aspirins, a golden Pippi. I leave the snack. I\'m scared of Rosy.'); return me('Aspirine scadute nel 1999 e un panino. Richiudo.','Aspirin expired in 1999 and a sandwich. Closing.'); });
avOn('look:hbed use:hbed',()=>me('Un lettino. Ancora caldo. Meglio non chiedere di chi.','A hospital bed. Still warm. Better not ask whose.'));
avOn('look:chairs use:chairs',()=>me('Le sedie della sala d\'attesa. Qui si aspetta così tanto che due signori ci sono morti. Ma non lo sanno ancora.','Waiting-room chairs. People wait so long two gentlemen died here. They don\'t know yet.'));
avOn('look:monitor',()=>me('Un monitor col battito cardiaco. È piatto. Ah no, è spento.','A heart monitor. It\'s flat. Oh no, it\'s just off.'));
avOn('look:cross',()=>me('Una croce rossa. Non so se indica il pronto soccorso o la speranza di uscirne.','A red cross. Not sure if it means first aid or the hope of leaving.'));
avOn('look:water use:water',()=>me('L\'erogatore d\'acqua. L\'unica cosa qui dentro che funziona senza ricetta.','The water cooler. The only thing here that works without a prescription.'));
/* ---------------- CIMITERO ---------------- */
AV_ENTER.cimitero={ after:async()=>{ if (!F().cimSeen){ F().cimSeen=1; avSave(); await me('Il cimitero. L\'unico posto in paese dove la gente sta zitta.','The cemetery. The only place in town where people keep quiet.'); } } };
avOn('look:ugo',()=>me(F().ugoAwake?'Ugo il becchino. Puzza di terra, grappa e piedi. In proporzioni uguali.':'Ugo il becchino. Dorme su una lapide, abbracciato a una pala, russando come un trattore.', F().ugoAwake?'Ugo the gravedigger. Smells of earth, grappa and feet. In equal parts.':'Ugo the gravedigger. Asleep on a headstone, hugging a shovel, snoring like a tractor.'));
avOn('talk:ugo',async()=>{ const f=F();
  if (!f.ugoAwake){ await me('Ugo! UGO! Svegliati!','Ugo! UGO! Wake up!'); return np('ugo','Zzz... non sono morto... zzz... non ancora... zzz... portatemi della grappa...','Zzz... not dead... zzz... not yet... zzz... bring me grappa...'); }
  await avTalk('ugo',[
    {id:'cert', q:['Mi serve il certificato di esistenza in vita.','I need a certificate of being alive.'], when:()=>f.modulo && !f.stampUgo, run:async()=>{ await np('ugo','Esistenza in vita? Ne ho visti tanti più vivi di te, e adesso stanno qui sotto. Va bene, te lo faccio. Ma prima un favore.','Proof of life? I\'ve seen plenty livelier than you, and now they\'re down here. Fine, I\'ll do it. But first a favour.');
      await np('ugo','Domani è l\'anniversario di mia moglie Assunta. Morta di noia, ascoltando me. Il vaso sulla sua tomba è vuoto da vent\'anni. Portami dei fiori, che non mi va di sentirla brontolare anche da lì sotto.','Tomorrow is my wife Assunta\'s anniversary. Died of boredom, listening to me. The vase on her grave has been empty twenty years. Bring flowers, I don\'t want her nagging from down there too.'); f.ugoAsked=1; avSave(); }},
    {id:'job', q:['Ti piace il tuo lavoro?','Do you like your job?'], run:()=>np('ugo','È l\'unico lavoro dove i clienti non si lamentano mai. E se lo fanno, scappo.','Only job where the customers never complain. And if they do, I run.')},
    {id:'crow', q:['Hai visto qualcuno strano stanotte?','Seen anyone strange tonight?'], run:()=>np('ugo','Alle due uno col mantello nero è passato davanti alla tomba di tuo nonno. Ha lasciato una piuma e ha riso. Che risata. Mi si è ghiacciata la grappa.','At two, someone in a black cloak passed by your grandpa\'s grave. Left a feather and laughed. What a laugh. My grappa froze.')},
    {id:'grandpa', q:['La tomba di mio nonno? Mio nonno è in Svizzera.','My grandpa\'s grave? My grandpa\'s in Switzerland.'], when:()=>(f['asked_ugo']||[]).includes('crow'), run:async()=>{ await np('ugo','Ernesto? C\'è una tomba col suo nome, sì. Ma è vuota. L\'ho scavata io nel 1987 e nessuno ci è mai entrato. Il funerale l\'hanno fatto con una bara piena di salami.','Ernesto? There\'s a grave with his name, yes. But it\'s empty. I dug it in 1987 and nobody ever went in. They held the funeral with a coffin full of salami.'); return me('Una bara piena di salami. Il fondo pensione. Il nonno è un genio o un pazzo. Probabilmente entrambi.','A coffin full of salami. The pension fund. Grandpa is a genius or a lunatic. Probably both.'); }}
  ]); });
avOn('use:ugo:grappa give:ugo:grappa',async()=>{ const f=F(); if (f.ugoAwake) return np('ugo','Ne ho già bevuta mezza. Il resto tienilo, ti servirà per qualcuno più disperato di me. Se esiste.','I already drank half. Keep the rest, you\'ll need it for someone more desperate than me. If they exist.');
  await me('Gli metto la bottiglia sotto il naso.','I hold the bottle under his nose.'); const n=npcOf('ugo'); if (n){ n.keep=0; npcPose(n,'jump','scared'); await avWait(800); npcPose(n,'drink','happy'); await avWait(1600); npcPose(n,'idle'); }
  f.ugoAwake=1; f.grappaHalf=1; avSave(); await np('ugo','AAAH! Ernesto?! Ah no, è la sua grappa. Resuscita i morti, questa. Ne bevo mezza, per ringraziarti.','AAAH! Ernesto?! Oh no, it\'s his grappa. This stuff raises the dead. I\'ll drink half, as thanks.'); return me('Mezza bottiglia in un sorso. E sta in piedi. Rispetto.','Half a bottle in one gulp. And still standing. Respect.'); });
avOn('give:ugo:fiori',async()=>{ const f=F(); if (!f.ugoAsked) return np('ugo','Fiori? Per me? Non sono ancora morto. Aspetta qualche anno.','Flowers? For me? I\'m not dead yet. Give it a few years.'); f.gaveFlowers=1; f.stampUgo=1; avDel('fiori');
  await np('ugo','Gerani e una rosa malata. Ad Assunta piaceranno: era malata anche lei, di carattere.','Geraniums and a sick rose. Assunta will love them: she was sick too, in the head.');
  await np('ugo','Ecco il timbro: "Si certifica che il soggetto respira, puzza e si lamenta. Quindi è vivo."','Here\'s the stamp: "It is certified that the subject breathes, stinks and complains. Therefore alive."');
  avSave(); return me('Secondo timbro. Sono ufficialmente vivo. Mia suocera ne sarà delusa.','Second stamp. I\'m officially alive. My mother-in-law will be disappointed.'); });
avOn('use:tomb1:fiori',()=>AV_S['give:ugo:fiori']());
avOn('look:tomb1',()=>me('"Qui giace Assunta, moglie di Ugo. Finalmente in pace." Il vaso è vuoto e pieno di ragnatele.','"Here lies Assunta, wife of Ugo. Finally at peace." The vase is empty and full of cobwebs.'));
avOn('look:tomb2',()=>me('"Qui giace Ernesto. Partito per la Svizzera. Mai arrivato. O forse sì." È la tomba del nonno! C\'è una piuma nera appoggiata sopra.','"Here lies Ernesto. Left for Switzerland. Never arrived. Or maybe did." It\'s grandpa\'s grave! There\'s a black feather on it.'));
avOn('take:tomb2',()=>me('La piuma si sbriciola appena la tocco. Era bruciata. Questo Corvo ha il senso del teatro.','The feather crumbles when I touch it. It was burnt. This Crow has a sense of drama.'));
avOn('look:tomb3',()=>me('"Qui giace il geometra Brambilla. Ha costruito mezzo paese. Che Dio lo perdoni, noi no."','"Here lies surveyor Brambilla. He built half the town. May God forgive him, we won\'t."'));
avOn('look:crypt',()=>me('La cappella della famiglia Pappalardo, quella del sindaco. Marmo, angeli e una targa: "Pagata con i soldi dei cittadini. Grazie."','The Pappalardo family chapel, the mayor\'s. Marble, angels and a plaque: "Paid for with citizens\' money. Thanks."'));
avOn('open:crypt use:crypt',async()=>{ await meAct('squat',1200); if (avCoin('crypt')) return me('Dentro, sull\'altare, un Pippi d\'oro. Il sindaco ruba anche ai morti. Io rubo al sindaco. Il cerchio della vita.','Inside, on the altar, a golden Pippi. The mayor steals even from the dead. I steal from the mayor. The circle of life.'); return me('Dentro c\'è solo l\'eco della corruzione.','Inside there\'s only the echo of corruption.'); });
avOn('look:gate',()=>me('Il cancello del cimitero. Cigola come mio nonno quando si alzava dal divano.','The cemetery gate. Creaks like grandpa getting off the sofa.'));
avOn('look:cypress',()=>me('Un cipresso. Dritto, scuro, triste. Come un vigile urbano.','A cypress. Straight, dark, sad. Like a traffic warden.'));
/* ---------------- KARAOKE & NONNA PINA ---------------- */
const KARAOKE_SONGS=[
  {title:['"Amore al Discount" — Nonna Pina & Orchestra','"Love at the Discount Store" — Granny Pina & Orchestra'], verses:[
    {line:['Ti ho conosciuto tra i surgelati,','I met you in the frozen aisle,'], opts:[['avevi i piselli già scongelati','your peas defrosting all the while'],['ma ti ho comprato in un altro negozio','but I bought you at another shop'],['e il mio cuore è un formaggio','and my heart is cheese, now stop']], ok:0},
    {line:['mi hai offerto un salame in offerta,','you offered me salami on sale,'], opts:[['ma io sono vegana da martedì','but I\'m vegan since Tuesday, oh well'],['e io ti ho dato la mia mano aperta','and I gave you my hand without fail'],['il mio gatto ha fame','my cat is hungry']], ok:1},
    {line:['ma alla cassa hai pagato coi buoni,','but at the till you paid with coupons,'], opts:[['e io ho capito che sei un taccagno','and I knew you were a cheapskate'],['tirchio, rozzo, e pure coglioni','stingy, rude, a pair of buffoons'],['la cassiera era bionda','the cashier was blonde']], ok:1},
    {line:['Amore al discount, amore scontato,','Love at the discount, love on sale,'], opts:[['mi hai lasciata col carrello bucato!','you left me with a broken trolley trail!'],['il frigo è pieno di prosciutto cotto','the fridge is full of cooked ham'],['ti amo ancora, Gino','I still love you, Gino']], ok:0}]},
  {title:['"Mia Suocera è un Vulcano"','"My Mother-in-Law Is a Volcano"'], verses:[
    {line:['Mia suocera la domenica viene a pranzo,','My mother-in-law comes on Sundays to dine,'], opts:[['e mangia come un elefante','and eats like an elephant, every time'],['porta la torta e un avanzo di manzo','brings a cake and leftover beef so fine'],['io scappo in Svizzera','I flee to Switzerland']], ok:1},
    {line:['la torta è secca come la sua pelle,','the cake is dry as her skin,'], opts:[['la mangio solo per farle un dispetto','I only eat it out of spite'],['il manzo sa di vecchie ciabatte, e di stelle','the beef tastes of old slippers and sin'],['sono allergico alle noci','I\'m allergic to nuts']], ok:1},
    {line:['quando parla trema la terra,','when she talks the earth shakes,'], opts:[['e il gatto si nasconde in bagno','and the cat hides in the loo'],['sembra l\'inizio di una guerra','sounds like the start of a war that breaks'],['il terremoto è previsto','the earthquake is forecast']], ok:1},
    {line:['Mia suocera è un vulcano, erutta veleno,','My mother-in-law is a volcano, spews venom,'], opts:[['speriamo che domenica si spenga almeno!','let\'s hope by Sunday she at least slows down, amen!'],['ti voglio bene comunque, mamma','I love you anyway, mum'],['domani piove','rain tomorrow']], ok:0}]},
  {title:['"Il Liscio della Dentiera"','"The Denture Waltz"'], verses:[
    {line:['Ballavo il liscio con la dentiera,','I danced the waltz with my false teeth,'], opts:[['era il 1970, una sera','it was 1970, a night beneath'],['mi è caduta nel minestrone','they fell in the minestrone'],['non so ballare','I can\'t dance']], ok:0},
    {line:['un giro, due giri, la testa girava,','one spin, two spins, my head spun round,'], opts:[['e la dentiera da sola ballava!','and my teeth kept dancing on the ground!'],['avevo bevuto un po\' di vino','I\'d drunk some wine'],['il maestro era cieco','the teacher was blind']], ok:0},
    {line:['l\'ho ritrovata nel piatto del prete,','I found them in the priest\'s plate,'], opts:[['che ha detto "amen" e ha mangiato le polpette','who said amen and ate the meatballs late'],['che mi ha detto "sorella, ne avete?"','who said "sister, are these yours, mate?"'],['il prete era simpatico','the priest was nice']], ok:1},
    {line:['Liscio, liscio, senza denti è più bello,','Smooth, smooth, it\'s better without teeth,'], opts:[['così non mordo nessun pipistrello','so no bat ever gets bitten beneath'],['ti bacio meglio, mio bel fringuello!','I kiss you better, my sweet little thief!'],['vado dal dentista','I go to the dentist']], ok:1}]}
];
avOn('look:pina',()=>me('Nonna Pina, presidente della Pro Loco dal 1971. Ottantasei anni, capelli fucsia, voce da sirena antiaerea.','Granny Pina, Tourist Board president since 1971. Eighty-six, fuchsia hair, air-raid-siren voice.'));
avOn('talk:pina',async()=>{ const f=F(); await avTalk('pina',[
  {id:'stamp', q:['Mi serve il parere favorevole della Pro Loco.','I need the Tourist Board\'s approval.'], when:()=>f.modulo && !f.stampPina, run:async()=>{
    await np('pina','Il timbro della Pro Loco? Te lo do solo se canti con me. Io canto una riga, tu canti quella dopo. Se sbagli la rima, fuori dalle palle.','The Tourist Board stamp? Only if you sing with me. I sing a line, you sing the next. Miss the rhyme and piss off.');
    const ok=await avKaraoke(KARAOKE_SONGS);
    if (!ok) return np('pina','Stonato come una campana rotta. Riprova quando hai imparato a rimare, cocco.','Off-key as a broken bell. Try again when you learn to rhyme, sweetie.');
    f.stampPina=1; avSave(); avTrophy('karaoke','Usignolo stonato: hai battuto Nonna Pina al karaoke.','Off-key nightingale: beat Granny Pina at karaoke.');
    await np('pina','Bravo! Non bravissimo, ma per uno che puzza di grappa, bravo. Timbro della Pro Loco!','Good! Not great, but for someone reeking of grappa, good. Tourist Board stamp!');
    return me('Terzo timbro. Ho cantato di suocere e dentiere alle tre di notte. Il mio psicologo ci campa un anno.','Third stamp. I sang about mothers-in-law and dentures at 3 a.m. My shrink will live off this for a year.'); }},
  {id:'vinyl', q:['Quel disco che usi come sottobicchiere...','That record you\'re using as a coaster...'], when:()=>f.djAsked && !f.gotVinyl, run:async()=>{ await np('pina','Il vinile di Max? Me l\'ha lasciato come pegno quando mi ha rotto la dentiera ballando la lambada. Poi la dentiera l\'ho persa al parco. Riportami la dentiera e il disco è tuo.','Max\'s record? He left it as a deposit when he broke my dentures dancing the lambada. Then I lost the dentures at the park. Bring me my dentures and the record\'s yours.'); f.pinaTeeth=1; avSave(); avOpen('park'); }},
  {id:'life', q:['Da quanto canti?','How long have you been singing?'], run:()=>np('pina','Dal 1950. Ho cantato a tre matrimoni, dodici funerali e un esorcismo. All\'esorcismo il diavolo è scappato per primo.','Since 1950. I\'ve sung at three weddings, twelve funerals and an exorcism. At the exorcism the devil left first.')},
  {id:'gino', q:['Conosci Gino il giardiniere?','Do you know Gino the gardener?'], once:true, run:()=>np('pina','Gino... il mio fidanzato segreto. Così segreto che lui non lo sa ancora.','Gino... my secret boyfriend. So secret he doesn\'t know yet.')}
  ]); });
avOn('give:pina:dentiera',async()=>{ const f=F(); avDel('dentiera');
  await np('pina','La mia dentiera! Dove l\'hai trovata? ...Nella fontana. Sì, me la ricordo, la fontana. Che serata. Non chiedere.','My dentures! Where did you find them? ...In the fountain. Yes, I remember the fountain. What a night. Don\'t ask.');
  await npcAct('pina','eat',1400); await np('pina','Ecco, sa ancora di cloro e di piccione. Tieni il disco di Max. Digli che se mi rompe di nuovo la dentiera, gli rompo le palle.','There, still tastes of chlorine and pigeon. Take Max\'s record. Tell him if he breaks my teeth again, I break his balls.');
  f.gotVinyl=1; avSave(); avAdd('vinile'); });
avOn('look:screen',()=>me('Lo schermo del karaoke. Scorrono le parole di "Mia Suocera è un Vulcano". Un classico.','The karaoke screen. Lyrics of "My Mother-in-Law Is a Volcano" scroll by. A classic.'));
avOn('look:mic use:mic',()=>me('Il microfono. Appiccicoso. Di cosa, non voglio saperlo.','The microphone. Sticky. With what, I don\'t want to know.'));
avOn('look:spkL look:spkR',()=>me('Una cassa enorme. Se parte il basso mi si sposta la dentiera. E non ce l\'ho.','A huge speaker. If the bass kicks in my dentures will move. And I don\'t have any.'));
avOn('open:spkR open:spkL',async()=>{ await meAct('squat',1000); if (avCoin('speaker')) return me('Dentro la cassa, un Pippi d\'oro che vibrava a tempo. Era lui che stonava.','Inside the speaker, a golden Pippi vibrating in time. That was what was off-key.'); return me('Fili, polvere e una cicca masticata.','Wires, dust and chewed gum.'); });
avOn('look:ball',()=>me('La palla stroboscopica. Gira e mi fa venire la nausea. Più del solito.','The disco ball. Spins and makes me sick. More than usual.'));
/* ---------------- PALESTRA (facoltativa) ---------------- */
avOn('look:rocky',()=>me('Rocky, personal trainer. Ha i bicipiti grossi come la mia testa e il cervello grosso come il mio mignolo.','Rocky, personal trainer. Biceps the size of my head, brain the size of my pinky.'));
avOn('talk:rocky',async()=>{ const f=F(); await avTalk('rocky',[
  {id:'chal', q:['Voglio la tua sfida delle flessioni.','I want your push-up challenge.'], when:()=>!f.pushups, run:async()=>{ await np('rocky','Venticinque flessioni in dieci secondi. Se ce la fai, ti do un premio. Se muori, ti do un abbonamento. Vai!','Twenty-five push-ups in ten seconds. Make it and you get a prize. Die and you get a membership. Go!');
    const ok=await avPushups(25,10); if (!ok) return np('rocky','Patetico. Mia nonna ne fa trenta. Ed è morta.','Pathetic. My grandma does thirty. And she\'s dead.');
    f.pushups=1; avSave(); avTrophy('pushups','Rocky approva: 25 flessioni senza morire.','Rocky approves: 25 push-ups without dying.'); try{ LIFE.pippi+=20; saveLife(); }catch(e){}
    await np('rocky','GRANDE! Ecco il premio: 20 Pippi e una pacca sul culo. Si chiama motivazione.','GREAT! Here\'s your prize: 20 Pippi and a slap on the arse. It\'s called motivation.'); }},
  {id:'tips', q:['Consigli per stare in forma?','Tips to stay fit?'], run:()=>np('rocky','Mangia proteine, dormi otto ore, evita lo stress. Tu fai il contrario di tutto, ma sei ancora vivo. Sei un caso di studio.','Eat protein, sleep eight hours, avoid stress. You do the opposite and you\'re still alive. You\'re a case study.')},
  {id:'crow', q:['Hai visto qualcosa stanotte?','See anything tonight?'], run:()=>np('rocky','Correvo sul lungomare alle due. Ho visto un tizio col mantello nero sul tetto del municipio. Ho pensato fosse Batman. Poi ho pensato: in questo paese? Al massimo Batman di Lidl.','I was jogging on the seafront at two. Saw a guy in a black cloak on the town hall roof. Thought it was Batman. Then thought: in this town? Discount Batman at best.')}
  ]); });
avOn('look:treadmill',()=>me('Il tapis roulant. Una macchina per correre senza andare da nessuna parte. Come la mia vita.','The treadmill. A machine for running without going anywhere. Like my life.'));
avOn('use:treadmill',async()=>{ await meAct('run',2400); return me('Trenta secondi e sto morendo. Il tapis roulant ride di me. Lo sento.','Thirty seconds and I\'m dying. The treadmill is laughing at me. I can feel it.'); });
avOn('look:weights',()=>me('Un bilanciere da 120 chili. Io sollevo al massimo la forchetta.','A 120-kilo barbell. The most I lift is a fork.'));
avOn('use:weights take:weights',async()=>{ await meAct('strain',2000); return me('Niente. Non si muove. Ho sentito solo un rumore. Credo fosse la mia ernia.','Nothing. It doesn\'t budge. I just heard a noise. I think it was my hernia.'); });
avOn('look:bag',()=>me('Il sacco da boxe. C\'è attaccata la foto del sindaco. Rocky è un patriota.','The punching bag. There\'s a photo of the mayor taped to it. Rocky is a patriot.'));
avOn('use:bag',async()=>{ await meAct('karate',1600); if (avCoin('bag')) return me('Pugno! Dal sacco cade un Pippi d\'oro. Il sindaco perde soldi anche in foto.','Punch! A golden Pippi falls out of the bag. The mayor loses money even in photos.'); return me('Pugno al sindaco. Liberatorio. Lo rifaccio. Lo rifaccio ancora.','Punch the mayor. Liberating. Again. And again.'); });
avOn('look:dumbbells take:dumbbells',()=>me('Manubri rosa da 1 chilo. Li prendo? No, me ne vergogno.','Pink 1-kilo dumbbells. Take them? No, I\'m ashamed.'));
avOn('look:gbottle',()=>me('La borraccia di Rocky. Dentro c\'è una cosa verde che si muove.','Rocky\'s water bottle. There\'s something green in it that moves.'));
/* ---------------- BOSCO & RINO ---------------- */
avOn('look:rino',()=>me('Rino l\'eremita. Vive nel bosco da trent\'anni. Ha un corvo di peluche sulla spalla e lo sguardo di chi ha visto Dio e gli ha chiesto i soldi indietro.','Rino the hermit. Lived in the woods thirty years. A stuffed crow on his shoulder and the look of a man who saw God and asked for a refund.'));
avOn('talk:rino',async()=>{ const f=F(); await avTalk('rino',[
  {id:'prophecy', q:['Mi dici il futuro?','Tell me my future?'], run:async()=>{ await np('rino','Vedo... un mestolo. Vedo... un corvo. Vedo... tuo nonno che ride in un posto pieno di sabbia e di Pippi.','I see... a ladle. I see... a crow. I see... your grandpa laughing in a place full of sand and Pippi.'); return np('rino','E vedo che hai le scarpe slacciate. Questo non è il futuro, è adesso.','And I see your shoes are untied. That\'s not the future, that\'s now.'); }},
  {id:'crow', q:['Chi è il Corvo?','Who is the Crow?'], run:()=>np('rino','Il Corvo è qualcuno che conosci. Uno che ride quando gli altri piangono. Uno che ha sempre mangiato bene al tavolo del paese. Più di così i funghi non mi dicono.','The Crow is someone you know. Someone who laughs when others cry. Someone who always ate well at the town\'s table. The mushrooms won\'t tell me more.')},
  {id:'wood', q:['Posso tagliare un po\' di legna?','Can I chop some firewood?'], when:()=>f.totoWood && !f.wood, run:()=>np('rino','Il tronco caduto puoi tagliarlo, è morto. Gli alberi vivi no: sono i miei amici. Specialmente quello là, Ottavio. Mi deve dei soldi.','You can chop the fallen log, it\'s dead. Not the living trees: they\'re my friends. Especially that one, Ottavio. He owes me money.')},
  {id:'shrooms', q:['Che funghi sono quelli?','What mushrooms are those?'], run:()=>np('rino','Funghi della conoscenza. Uno ti fa vedere la verità. Due ti fanno vedere tua nonna. Tre ti fanno diventare tua nonna.','Mushrooms of knowledge. One shows you the truth. Two show you your grandma. Three turn you into your grandma.')}
  ]); });
avOn('look:log',()=>me('Un tronco caduto, secco. Perfetto per un forno a legna. O per sedersi e piangere.','A fallen, dry log. Perfect for a wood oven. Or for sitting and crying.'));
avOn('use:log:ascia',async()=>{ const f=F(); if (f.wood) return me('Ho già abbastanza legna. Se continuo Rino mi denuncia agli alberi.','I have enough wood. Keep going and Rino reports me to the trees.'); await meAct('swing',2400); f.wood=1; avSave(); avAdd('legna');
  await np('rino','Piano! Quel tronco era il nonno di Ottavio!','Easy! That log was Ottavio\'s grandpa!'); return me('Un bel fascio di legna secca. Totò avrà il suo forno.','A nice bundle of dry wood. Totò will get his oven.'); });
avOn('use:log',()=>me('A mani nude? Mi spezzo prima io del tronco.','With bare hands? I\'d break before the log.'));
avOn('look:campfire',()=>me('Il falò di Rino. Ci sta cuocendo qualcosa. Ha la coda.','Rino\'s campfire. Something is cooking on it. It has a tail.'));
avOn('look:mushrooms',()=>me('Funghi viola a pois gialli. Se fossero commestibili ci sarebbe la fila. Non c\'è la fila.','Purple mushrooms with yellow spots. If they were edible there\'d be a queue. There\'s no queue.'));
avOn('take:mushrooms',()=>{ if (avHas('funghi')||F().ateShrooms) return me('Basta funghi. Ne ho già abbastanza per tre viaggi.','Enough mushrooms. Got enough for three trips.'); avAdd('funghi'); return me('Raccolgo un fungo. Mi sembra che mi abbia salutato.','I pick a mushroom. I think it waved at me.'); });
avOn('use:me:funghi',async()=>{ avDel('funghi'); F().ateShrooms=1; avSave(); setPose('zombie'); document.body.style.filter='hue-rotate(160deg) saturate(2)'; await me('Mangio il fungo. ...Oh. Oh no. Gli alberi cantano. Cantano Nonna Pina.','I eat the mushroom. ...Oh. Oh no. The trees are singing. They\'re singing Granny Pina.');
  await me('Vedo il nonno su un\'isola. Mi saluta con un mestolo d\'oro e dice: "Il Corvo ha il becco unto di risotto". Poi si trasforma in un salame.','I see grandpa on an island. He waves a golden ladle and says: "The Crow\'s beak is greasy with risotto". Then he turns into a salami.');
  document.body.style.filter=''; setPose('idle'); avTrophy('funghi','Viaggio mistico nel bosco. Non chiedere.','Mystic trip in the woods. Don\'t ask.'); return me('...Passato. Il becco unto di risotto. Ricordamelo, taccuino.','...It\'s over. Greasy with risotto. Remember that, notebook.'); });
avOn('look:trees',()=>me('Alberi. Uno ha la faccia. Spero sia la corteccia.','Trees. One has a face. I hope it\'s the bark.'));
/* ---------------- TACCUINO & OGGETTI ---------------- */
avOn('look:taccuino use:me:taccuino',()=>{ const f=F(); const notes=[];
  if (f.peppeTip) notes.push(T('Peppe: ciuffo lucido + pesce → spiaggia.','Peppe: shiny quiff + fish → beach.'));
  if (f.baffoTold) notes.push(T('Baffo: Tonino alla bisca; parola d\'ordine a metà.','Baffo: Tonino at the den; half a password.'));
  if (f.toninoConf) notes.push(T('Tonino: rubato per il Corvo, perso a poker con la Contessa.','Tonino: stole it for the Crow, lost it at poker to the Countess.'));
  if (f.marisaSaw) notes.push(T('Marisa: alle 2 Gaspare dal Magazzino 7 al Municipio con qualcosa di luccicante.','Marisa: at 2 a.m. Gaspare went from Warehouse 7 to the Town Hall carrying something shiny.'));
  if (f.ateShrooms) notes.push(T('Fungo: "il Corvo ha il becco unto di risotto". (??)','Mushroom: "the Crow\'s beak is greasy with risotto". (??)'));
  return me(notes.length? T('Dal taccuino: ','From the notebook: ')+notes.join(' · ') : T('Il taccuino è vuoto. Come la mia testa prima del caffè.','The notebook is empty. Like my head before coffee.'), ''); });
avOn('look:lente',()=>me('La lente del nonno. Serve a vedere le cose piccole. Tipo i dettagli. O il mio stipendio.','Grandpa\'s magnifier. For seeing small things. Like details. Or my salary.'));
avOn('look:modulo',()=>{ const f=F(); c1HealStamps(); const n=(f.stampDoc?1:0)+(f.stampUgo?1:0)+(f.stampPina?1:0); return me(`Modulo B-52. Timbri: ${n}/3. Medico: ${f.stampDoc?'✔':'✘'}. Cimitero: ${f.stampUgo?'✔':'✘'}. Pro Loco: ${f.stampPina?'✔':'✘'}.`,`Form B-52. Stamps: ${n}/3. Doctor: ${f.stampDoc?'✔':'✘'}. Cemetery: ${f.stampUgo?'✔':'✘'}. Tourist Board: ${f.stampPina?'✔':'✘'}.`); });
avOn('look:distintivo',()=>me('Il distintivo di Investigatore Comunale. È di latta e ha un errore: c\'è scritto "Investigatore Comunaie".','The Town Investigator badge. Tin, with a typo: it says "Town Investigatr".'));
avOn('look:chiavi',()=>me('Le chiavi di casa. Ancora umide. Non annusarle. Le ho annusate.','House keys. Still damp. Don\'t smell them. I smelled them.'));
avOn('look:guanti',()=>me('Guanti di gomma. Dopo il cesso, li considero radioattivi.','Rubber gloves. After the toilet, I consider them radioactive.'));
avOn('look:barattolo',()=>me('Sottaceti misti. Scadenza: illeggibile. Coraggio: richiesto.','Mixed pickles. Expiry: unreadable. Courage: required.'));
avOn('look:vasetto',()=>me('Un barattolo vuoto. Puzza di aceto. Pronto per... il suo destino.','An empty jar. Smells of vinegar. Ready for... its destiny.'));
avOn('look:campione',()=>me('Il mio campione. Caldo. Giallo. Non lo guardo troppo.','My sample. Warm. Yellow. I don\'t look at it too long.'));
avOn('look:torcia',()=>me('Una torcia. Fa luce. Più di certi politici.','A torch. Gives light. More than some politicians.'));
avOn('look:grappa',()=>me(F().grappaHalf?'Mezza bottiglia di grappa del nonno. L\'altra metà è dentro Ugo.':'Grappa del nonno, 70 gradi. Si potrebbe usare per svegliare i morti. O per sverniciare.', F().grappaHalf?'Half a bottle of grandpa\'s grappa. The other half is inside Ugo.':'Grandpa\'s grappa, 70°. Could wake the dead. Or strip paint.'));
avOn('use:me:grappa',()=>me('Berla io? A 70 gradi? Ci tengo al fegato. Più o meno. Diciamo meno.','Drink it myself? At 70°? I care about my liver. Sort of. Less than sort of.'));
avOn('look:fiori',()=>me('Gerani e una rosa malata. Il mazzo perfetto per un funerale o per una suocera.','Geraniums and a sick rose. Perfect for a funeral or a mother-in-law.'));
avOn('look:baffi',()=>me('Baffi finti del nonno. Con questi sembro un ispettore della Finanza. O un pornoattore anni \'70. No, ispettore.','Grandpa\'s fake moustache. With these I look like a tax inspector. Or a 70s... no, tax inspector.'));
avOn('look:retino',()=>me('Il retino da pesca del nonno. Ha pescato più scarpe che pesci.','Grandpa\'s fishing net. Caught more shoes than fish.'));
avOn('look:polvere',()=>me('Caffè macinato di Nico. Profuma di vita e di pettegolezzi.','Nico\'s ground coffee. Smells of life and gossip.'));
avOn('look:moka',()=>me('La moka della nonna. Vuota. Serve il caffè.','Grandma\'s coffee pot. Empty. Needs coffee.'));
avOn('use:polvere:moka',()=>{ avDel('polvere'); avSwap('moka','mokapiena'); return me('Carico la moka. Ora va solo messa sul fuoco.','I load the pot. Now it just needs the stove.'); });
avOn('look:mokapiena',()=>me('Moka carica. Va messa sui fornelli della cucina.','Loaded coffee pot. Goes on the kitchen stove.'));
avOn('give:marisa:mokapiena',()=>np('marisa','E io che ci faccio con la moka cruda? La mastico? Scaldala, genio.','What do I do with a raw coffee pot? Chew it? Heat it up, genius.'));
avOn('look:caffe',()=>me('Caffè bollente. Non lo bevo. Non lo bevo. Non lo... no, non lo bevo.','Piping hot coffee. Not drinking it. Not drinking it. Not... no, not drinking it.'));
avOn('use:me:caffe',()=>me('Lo vorrei tanto. Ma serve a qualcuno più disperato di me. Raro, ma esiste.','I want it so bad. But someone more desperate needs it. Rare, but they exist.'));
avOn('look:ascia',()=>me('Un\'ascia. Mi sento un boscaiolo. Un boscaiolo in impermeabile, tipo serial killer.','An axe. I feel like a lumberjack. A lumberjack in a trench coat, serial-killer style.'));
avOn('look:legna',()=>me('Legna secca di prima qualità. Il nonno di Ottavio.','Top-quality dry wood. Ottavio\'s grandpa.'));
avOn('look:basilico',()=>me('Basilico fresco. Profuma di domenica.','Fresh basil. Smells like Sunday.'));
avOn('look:funghi',()=>me('Funghi viola. Mi fissano.','Purple mushrooms. They stare at me.'));
